WITH metrics AS (SELECT *, LAG(duration_sec, 1) OVER (PARTITION BY session_id ORDER BY event_time, id) AS prev_duration_sec, SUM(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_duration_sec, ROW_NUMBER() OVER (PARTITION BY page ORDER BY event_time DESC, id) AS event_seq FROM web_events) SELECT DATE_TRUNC('WEEK', event_time) AS week_start, session_id, AVG(event_seq) AS avg_event_seq, SIZE(COLLECT_SET(page)) AS num_pages, COUNT(*) AS event_count, MAX(prev_duration_sec) FILTER (WHERE page = '/checkout') AS checkout_max_prev_duration_sec, PERCENTILE_APPROX(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, COUNT_IF(page = '/home') AS home_events FROM metrics GROUP BY 1, 2 HAVING MAX(prev_duration_sec) FILTER (WHERE page = '/checkout') < 0 ORDER BY avg_event_seq DESC NULLS FIRST;
